// energy/degradation sketch for: Advanced Material-to-Product Generator
let c = 1.0; const samples = [];
for (let i = 0; i < 536; i++) { c *= 0.9998; if (i % 100 === 0) samples.push(+c.toFixed(4)); }
console.log(JSON.stringify({ cycles: 536, retention: +c.toFixed(4), samples: samples,
  eolReached: c < 0.8 }));

